    int moveBookmark(@Param("id") Long id, @Param("memberId") Long memberId,
                     @Param("folderId") Long folderId);
    List<BookmarkListRow> findMyBookmarks(@Param("memberId") Long memberId,
                                          @Param("viewerRole") String viewerRole,
                                          @Param("folderMode") String folderMode,
                                          @Param("folderId") Long folderId,
                                          @Param("cursorAt") LocalDateTime cursorAt,
                                          @Param("cursorId") Long cursorId,
                                          @Param("limit") int limit);
}

